export const Schema = z.object({
    时间: z
        .object({
        周几: z.enum(['周一', '周二', '周三', '周四', '周五', '周六', '周日']),
        小时: z.coerce.number(),
        分钟: z.coerce.number(),
    })
        .transform(({ 周几, 小时, 分钟 }) => {
        const 一周 = ['周一', '周二', '周三', '周四', '周五', '周六', '周日'];
        const 总分钟 = Math.max(0, 小时 * 60 + 分钟);
        const 进位小时 = Math.floor(总分钟 / 60);
        const 索引 = (((一周.indexOf(周几) + Math.floor(进位小时 / 24)) % 7) + 7) % 7;
        return { 周几: 一周[索引], 小时: 进位小时 % 24, 分钟: 总分钟 % 60 };
    }),
    位置: z.object({
        区域: z.string(),
        地点: z.string(),
    }),
    穿着: z.record(z.enum(['头部', '面部', '上衣', '下装', '腿部', '脚部', '胸罩', '内裤']), z.string().describe('穿着描述')),
    束缚: z.record(z.enum([
        '眼部',
        '口部',
        '上肢',
        '手腕',
        '胸部',
        '乳头',
        '腰部',
        '身体',
        '阴部',
        '阴蒂',
        '小穴',
        '后穴',
        '腿部',
        '脚踝',
        '足部',
    ]), z.string().describe('拘束或玩具描述')),
    性欲值: z.coerce.number().transform(v => _.clamp(v, 0, 100)),
    心情: z.string(),
    露出经验: z.coerce.number().transform(v => Math.max(0, v)),
    道具库存: z
        .record(z.string().describe('道具名'), z.object({
        描述: z.string(),
        数量: z.coerce.number().prefault(1),
    }))
        .transform(data => _.pickBy(data, ({ 数量 }) => 数量 > 0)),
    当前携带: z.array(z.string().describe('道具名')),
    知名度: z.coerce.number().transform(v => _.clamp(v, 0, 100)),
    已踩点: z.array(z.string().describe('地点')),
});
